// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        // admissible: the caller is not the current owner (initial owner is address(0))
        // and the proposed new owner differs from the current one
        vm.assume(actor != address(0));
        vm.assume(newOwner != c.owner());

        address ownerBefore = c.owner();

        vm.prank(actor);
        try c.transferOwnership(newOwner) {
            // call succeeded
        } catch {
            // call reverted
        }

        // GENERAL RULE: a non-owner's transferOwnership attempt NEVER changes owner.
        assertTrue(c.owner() == ownerBefore);
    }
}
